    def bark():
        print("Woof")
d = Dog("Brownie")
d.bark()

class Account:
    def __init__(self, owner, balance):
        self.owner = owner
        self.balance = balance
    def deposit(self, amount):
        self.balance = self.balance + amount
    def withdraw(self, amount):
        self.balance = self.balance - amount
acc = Account("Ana", 500)
acc.deposit(200)
acc.withdraw(150)
acc.deposit(50)
print(acc.balance)

class Rectangle:
    def __init__(self, length, width):
        self.length = length
        self.width = width
    def area(self):
        return self.length * self.width
    def show(self):
        print(self.length * self.width)
r = Rectangle(4, 3)
total = r.area() + r.area()
print(total)
x = r.show()
print(x)

class Calculator:
    def __init__(self, a, b):
        self.a = a
        self.b = b
    def add(self):
        return self.a + self.b
    def multiply(self):
        return self.a * self.b
    def combined(self):
        return self.add() + self.multiply()
c = Calculator(4, 5)
print(c.combined())

